describe('Notification Message Rendered', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
  });

  it('should display a success notification when clicking the action link', () => {
    // Verify initial state
    cy.get('[data-testid="flash-message"]').should('not.exist');
    cy.get('[data-testid="flash-container"]').should('not.exist');

    // Click the action link
    cy.get('[data-testid="click-here-button"]').click();

    // Verify success notification appears
    cy.get('[data-testid="flash-container"]').should('be.visible');
    cy.get('[data-testid="flash-message"]').should('be.visible');
    cy.get('[data-testid="flash-message"]').should('contain', 'Action successful');

    // Verify notification has close button
    cy.get('[data-testid="flash-close-icon"]').should('be.visible');

    // Verify notification can be dismissed
    cy.get('[data-testid="flash-close-icon"]').click();
    cy.get('[data-testid="flash-message"]').should('not.exist');
    cy.get('[data-testid="flash-container"]').should('not.exist');
  });

  it('should display an error notification when action fails and handle dismissal', () => {
    // Intercept the API call to simulate failure
    cy.intercept('GET', '/api/action/fail').as('actionFailed');

    // Click the action link
    cy.get('[data-testid="click-here-button"]').click();

    // Wait for the failed API call
    cy.wait('@actionFailed');

    // Verify error notification appears
    cy.get('[data-testid="flash-container"]').should('be.visible');
    cy.get('[data-testid="flash-message"]').should('be.visible');
    cy.get('[data-testid="flash-message"]').should('contain', 'Action unsuccessful');

    // Verify notification has close button
    cy.get('[data-testid="flash-close-icon"]').should('be.visible');

    // Verify notification can be dismissed
    cy.get('[data-testid="flash-close-icon"]').click();
    cy.get('[data-testid="flash-message"]').should('not.exist');
    cy.get('[data-testid="flash-container"]').should('not.exist');
  });
});
